#include <stdatomic.h>

static atomic_size_t refcount;      /* _Atomic: alignment and type are checked by the compiler */

bool try_acquire(_Atomic(int) *flag) {
    int expected = 0;
    return atomic_compare_exchange_weak_explicit(flag, &expected, 1,
        memory_order_acquire,     /* success: we now hold the resource */
        memory_order_relaxed);    /* failure: weaker is allowed, and is correct */
}

void publish(void *obj) {
    atomic_store_explicit(&shared, obj, memory_order_release);  /* publishes prior writes */
}
void *consume(void) {
    return atomic_load_explicit(&shared, memory_order_acquire); /* sees everything published */
}
